# Function to export to CSV
def export_to_csv(ideas, filename="new_directory_ideas_151_175.csv"):
    import csv

    if not ideas:
        print("No ideas to export")
        return

    fieldnames = ideas[0].keys()

    with open(filename, 'w', newline='', encoding='utf-8') as csvfile:
        writer = csv.DictWriter(csvfile, fieldnames=fieldnames, quoting=csv.QUOTE_ALL)
        writer.writeheader()
        writer.writerows(ideas)

    print(f"Exported {len(ideas)} ideas to {filename}")

if __name__ == "__main__":
    # Print summary
    print(f"Created {len(new_directory_ideas)} new directory startup ideas (DIR-151 to DIR-175)")
    print("\nCategories covered:")
    categories = {}
    for idea in new_directory_ideas:
        cat = idea.get('subcategory', idea.get('category'))
        categories[cat] = categories.get(cat, 0) + 1
    for cat, count in sorted(categories.items(), key=lambda x: -x[1]):
        print(f"  - {cat}: {count}")

    print("\nLEAP Score Summary:")
    leap_scores = [idea['leap_total'] for idea in new_directory_ideas]
    print(f"  Average LEAP: {sum(leap_scores)/len(leap_scores):.1f}")
    print(f"  Highest LEAP: {max(leap_scores)} ({[i['title'] for i in new_directory_ideas if i['leap_total']==max(leap_scores)][0]})")
    print(f"  Lowest LEAP: {min(leap_scores)} ({[i['title'] for i in new_directory_ideas if i['leap_total']==min(leap_scores)][0]})")

    # Export to CSV
    export_to_csv(new_directory_ideas)
